package com.termux.app.terminow;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertTrue;

import com.jcraft.jsch.JSch;
import com.jcraft.jsch.KeyPair;

import org.junit.Test;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

/**
 * End to end for {@link TerminowPpk#exportKeyFile}: a key generated by JSch and saved encrypted on
 * disk is exported to a .ppk, read back with {@link TerminowPpk#convert}, and the resulting OpenSSH
 * key loads to the very same public key — proving the private material survived the round trip for
 * each key type, including the on-disk decryption.
 */
public class TerminowPpkExportTest {

    private static final String PASS = "test-passphrase";

    private void roundTrip(int type, int bits, String expectType, boolean encryptOnDisk) throws Exception {
        JSch jsch = new JSch();
        KeyPair generated = KeyPair.genKeyPair(jsch, type, bits);
        byte[] expectedPublic = generated.getPublicKeyBlob();
        File file = File.createTempFile("terminow-key-", "");
        file.deleteOnExit();
        // JSch can encrypt RSA/ECDSA on disk, but not Ed25519 in its classic format; the real app
        // reads an already-encrypted Ed25519 fine, so Ed25519 is written unencrypted here.
        if (encryptOnDisk) generated.writePrivateKey(file.getPath(), PASS.getBytes(StandardCharsets.UTF_8));
        else generated.writePrivateKey(file.getPath());
        generated.dispose();

        // Export to an encrypted .ppk with the same passphrase
        String ppk = TerminowPpk.exportKeyFile(file, PASS, "zoom32");
        assertTrue(TerminowPpk.isPpk(ppk));
        assertTrue(ppk.contains("PuTTY-User-Key-File-3: " + expectType));
        assertTrue(ppk.contains("Encryption: aes256-cbc"));

        // Read the .ppk back and load the resulting OpenSSH key: same public key => same key
        TerminowPpk.Result result = TerminowPpk.convert(ppk, PASS);
        KeyPair loaded = KeyPair.load(jsch, result.privateKey.getBytes(StandardCharsets.UTF_8), null);
        assertArrayEquals("round-tripped public key differs for " + expectType, expectedPublic, loaded.getPublicKeyBlob());
        loaded.dispose();
        //noinspection ResultOfMethodCallIgnored
        file.delete();
    }

    // An unencrypted openssh-key-v1 Ed25519 private key, built from a seed, so no private key file
    // is committed. JSch loads it, and exportKeyFile reads the seed from the decrypted key pair.
    private static byte[] opensshEd25519(byte[] seed) {
        org.bouncycastle.crypto.params.Ed25519PrivateKeyParameters prv =
            new org.bouncycastle.crypto.params.Ed25519PrivateKeyParameters(seed, 0);
        byte[] pub = prv.generatePublicKey().getEncoded();
        byte[] publicBlob = sshString("ssh-ed25519".getBytes(StandardCharsets.US_ASCII), pub);
        byte[] secret = new byte[64];
        System.arraycopy(seed, 0, secret, 0, 32);
        System.arraycopy(pub, 0, secret, 32, 32);
        java.io.ByteArrayOutputStream priv = new java.io.ByteArrayOutputStream();
        writeRaw(priv, new byte[]{0x11, 0x22, 0x33, 0x44}); // check int 1
        writeRaw(priv, new byte[]{0x11, 0x22, 0x33, 0x44}); // check int 2 (equal)
        writeRaw(priv, sshString("ssh-ed25519".getBytes(StandardCharsets.US_ASCII)));
        writeRaw(priv, sshString(pub));
        writeRaw(priv, sshString(secret));
        writeRaw(priv, sshString("terminow-test".getBytes(StandardCharsets.US_ASCII)));
        for (int i = 1; priv.size() % 8 != 0; i++) priv.write(i);

        java.io.ByteArrayOutputStream file = new java.io.ByteArrayOutputStream();
        writeRaw(file, "openssh-key-v1\0".getBytes(StandardCharsets.US_ASCII));
        writeRaw(file, sshString("none".getBytes(StandardCharsets.US_ASCII)));
        writeRaw(file, sshString("none".getBytes(StandardCharsets.US_ASCII)));
        writeRaw(file, sshString(new byte[0]));
        writeRaw(file, new byte[]{0, 0, 0, 1});
        writeRaw(file, sshString(publicBlob));
        writeRaw(file, sshString(priv.toByteArray()));
        String b64 = java.util.Base64.getEncoder().encodeToString(file.toByteArray());
        StringBuilder pem = new StringBuilder("-----BEGIN OPENSSH PRIVATE KEY-----\n");
        for (int i = 0; i < b64.length(); i += 70) pem.append(b64, i, Math.min(b64.length(), i + 70)).append('\n');
        pem.append("-----END OPENSSH PRIVATE KEY-----\n");
        return pem.toString().getBytes(StandardCharsets.UTF_8);
    }

    private static void writeRaw(java.io.ByteArrayOutputStream out, byte[] data) {
        out.write(data, 0, data.length);
    }

    private static byte[] sshString(byte[]... parts) {
        java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
        for (byte[] p : parts) {
            out.write(p.length >>> 24); out.write(p.length >>> 16); out.write(p.length >>> 8); out.write(p.length);
            out.write(p, 0, p.length);
        }
        return out.toByteArray();
    }

    @Test
    public void ed25519RoundTrips() throws Exception {
        byte[] seed = new byte[32];
        for (int i = 0; i < 32; i++) seed[i] = (byte) (i * 11 + 5);
        File file = File.createTempFile("tn-ed-", "");
        file.deleteOnExit();
        Files.write(file.toPath(), opensshEd25519(seed));

        JSch jsch = new JSch();
        KeyPair expected = KeyPair.load(jsch, file.getPath());
        byte[] expectedPublic = expected.getPublicKeyBlob();
        expected.dispose();

        // Export to an encrypted .ppk (exercising the Ed25519 seed extraction), then read it back
        String ppk = TerminowPpk.exportKeyFile(file, PASS, "zoom32");
        assertTrue(ppk.contains("PuTTY-User-Key-File-3: ssh-ed25519"));
        assertTrue(ppk.contains("Encryption: aes256-cbc"));
        TerminowPpk.Result result = TerminowPpk.convert(ppk, PASS);
        KeyPair loaded = KeyPair.load(jsch, result.privateKey.getBytes(StandardCharsets.UTF_8), null);
        assertArrayEquals("Ed25519 round-trip changed the key", expectedPublic, loaded.getPublicKeyBlob());
        loaded.dispose();
        Files.deleteIfExists(file.toPath());
    }

    @Test
    public void rsaRoundTrips() throws Exception {
        roundTrip(KeyPair.RSA, 2048, "ssh-rsa", true); // encrypted on disk: covers decryption
    }

    @Test
    public void ecdsaRoundTrips() throws Exception {
        roundTrip(KeyPair.ECDSA, 256, "ecdsa-sha2-nistp256", true);
    }

    @Test
    public void wrongPassphraseIsRejected() throws Exception {
        JSch jsch = new JSch();
        KeyPair generated = KeyPair.genKeyPair(jsch, KeyPair.RSA, 2048);
        File file = File.createTempFile("terminow-key-", "");
        file.deleteOnExit();
        generated.writePrivateKey(file.getPath(), PASS.getBytes(StandardCharsets.UTF_8));
        generated.dispose();
        try {
            TerminowPpk.exportKeyFile(file, "wrong", "k");
            org.junit.Assert.fail("expected a passphrase error");
        } catch (TerminowPpk.PassphraseException expected) {
            // good
        } finally {
            Files.deleteIfExists(file.toPath());
        }
    }
}
